import os
import json
import base64
import secrets
from typing import Dict, Any, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad


class EnvelopeEncryptionError(Exception):
    pass


class AWSEnvelopeEncryptor:
    def __init__(self, kms_key_id: str, region_name: Optional[str] = None):
        if not kms_key_id:
            raise ValueError("kms_key_id is required")
        self.kms_key_id = kms_key_id
        self.kms = boto3.client("kms", region_name=region_name)

    def encrypt(self, plaintext: bytes, encryption_context: Optional[Dict[str, str]] = None) -> Dict[str, Any]:
        try:
            data_key_resp = self.kms.generate_data_key(
                KeyId=self.kms_key_id,
                KeySpec="AES_256",
                EncryptionContext=encryption_context or {},
            )
            plaintext_data_key = data_key_resp["Plaintext"]
            encrypted_data_key = data_key_resp["CiphertextBlob"]

            iv = secrets.token_bytes(16)
            cipher = AES.new(plaintext_data_key, AES.MODE_CBC, iv=iv)
            ciphertext = cipher.encrypt(pad(plaintext, AES.block_size))

            return {
                "kms_key_id": self.kms_key_id,
                "encrypted_data_key": base64.b64encode(encrypted_data_key).decode("utf-8"),
                "iv": base64.b64encode(iv).decode("utf-8"),
                "ciphertext": base64.b64encode(ciphertext).decode("utf-8"),
                "encryption_context": encryption_context or {},
                "algorithm": "AES-256-CBC",
                "provider": "aws-kms",
            }
        except (BotoCoreError, ClientError, KeyError, ValueError) as e:
            raise EnvelopeEncryptionError(f"Envelope encryption failed: {e}") from e

    def decrypt(self, envelope: Dict[str, Any]) -> bytes:
        try:
            encrypted_data_key = base64.b64decode(envelope["encrypted_data_key"])
            iv = base64.b64decode(envelope["iv"])
            ciphertext = base64.b64decode(envelope["ciphertext"])
            encryption_context = envelope.get("encryption_context") or {}

            data_key_resp = self.kms.decrypt(
                CiphertextBlob=encrypted_data_key,
                EncryptionContext=encryption_context,
            )
            plaintext_data_key = data_key_resp["Plaintext"]

            cipher = AES.new(plaintext_data_key, AES.MODE_CBC, iv=iv)
            padded_plaintext = cipher.decrypt(ciphertext)
            return unpad(padded_plaintext, AES.block_size)
        except (BotoCoreError, ClientError, KeyError, ValueError) as e:
            raise EnvelopeEncryptionError(f"Envelope decryption failed: {e}") from e


def encrypt_bytes(plaintext: bytes, kms_key_id: str, region_name: Optional[str] = None,
                  encryption_context: Optional[Dict[str, str]] = None) -> str:
    encryptor = AWSEnvelopeEncryptor(kms_key_id=kms_key_id, region_name=region_name)
    envelope = encryptor.encrypt(plaintext, encryption_context=encryption_context)
    return json.dumps(envelope)


def decrypt_bytes(envelope_json: str, region_name: Optional[str] = None) -> bytes:
    envelope = json.loads(envelope_json)
    kms_key_id = envelope.get("kms_key_id")
    if not kms_key_id:
        raise ValueError("Envelope is missing kms_key_id")
    encryptor = AWSEnvelopeEncryptor(kms_key_id=kms_key_id, region_name=region_name)
    return encryptor.decrypt(envelope)
